const e=/\[Person:(\d*):([\w -]*)\]/gm,t=/\[Activity:(\d*):(.*)\]/gm,o=/\[Organization:(\d*):(.*)\]/gm,a=/\[Project:(\d*):(.*)\]/gm,n="/person/show/",c="/project/show/",s="/organization/show/",i="/activites-de-recherche/fiche/",g={log(r){return this.organization(this.activity(this.person(this.project(r))))},person(r){return r.replace(e,'<a href="'+n+'$1" class="person">$2</a>')},activity(r){return r.replace(t,'<a href="'+i+'$1" class="person">$2</a>')},organization(r){return r.replace(o,'<a href="'+s+'$1" class="organization">$2</a>')},project(r){return r.replace(a,'<a href="'+c+'$1" class="project">$2</a>')}};export{g as t};
